ALTER TABLE [dbo].[admission_form] ADD  CONSTRAINT [DF_admission_form_is_approved]  DEFAULT ((0)) FOR [is_approved]
GO
ALTER TABLE [dbo].[admission_form] ADD  CONSTRAINT [DF_admission_form_approval_token]  DEFAULT (newid()) FOR [approval_token]
GO
ALTER TABLE [dbo].[admission_form] ADD  CONSTRAINT [DF_admission_form_approval_requested_at]  DEFAULT (sysdatetime()) FOR [approval_requested_at]
GO
ALTER TABLE [dbo].[admission_form] ADD  CONSTRAINT [DF_admission_form_created_at]  DEFAULT (sysdatetime()) FOR [created_at]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_approval_fields] CHECK  (([is_approved]=(0) AND [approver_ad_username] IS NULL AND [approver_display_name] IS NULL AND [approved_at] IS NULL OR [is_approved]=(1) AND [approver_ad_username] IS NOT NULL AND [approver_display_name] IS NOT NULL AND [approved_at] IS NOT NULL))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_approval_fields]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_contractor_name] CHECK  (([visitor_status]=N'Контрагент' AND [contractor_name] IS NOT NULL AND ltrim(rtrim([contractor_name]))<>N'' OR [visitor_status]<>N'Контрагент' AND [contractor_name] IS NULL))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_contractor_name]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_dates] CHECK  (([visit_date_to]>=[visit_date_from] AND [visit_date_to]<dateadd(month,(1),[visit_date_from])))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_dates]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_gate_number] CHECK  (([has_vehicle_access]=(0) AND [gate_number] IS NULL OR [has_vehicle_access]=(1) AND [visit_place]=N'Офис' AND [gate_number] IS NULL OR [has_vehicle_access]=(1) AND [visit_place]<>N'Офис' AND ([gate_number]=(4) OR [gate_number]=(3) OR [gate_number]=(2) OR [gate_number]=(1))))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_gate_number]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_vehicle_fields] CHECK  (([has_vehicle_access]=(0) AND [vehicle_number] IS NULL AND [gate_number] IS NULL AND [requires_weighing] IS NULL OR [has_vehicle_access]=(1) AND [vehicle_number] IS NOT NULL AND ltrim(rtrim([vehicle_number]))<>N'' AND [requires_weighing] IS NOT NULL))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_vehicle_fields]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_visit_place] CHECK  (([visit_place]=N'Территория' OR [visit_place]=N'Склад ГП' OR [visit_place]=N'Производство холодильников' OR [visit_place]=N'Производство стиральных машин' OR [visit_place]=N'Офис'))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_visit_place]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_visitor_status] CHECK  (([visitor_status]=N'Кандидат' OR [visitor_status]=N'Курьер' OR [visitor_status]=N'Сотрудник БСХ' OR [visitor_status]=N'Контрагент'))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_visitor_status]
GO
ALTER TABLE [dbo].[admission_form]  WITH CHECK ADD  CONSTRAINT [CK_admission_form_weight_kg] CHECK  (([weighing_1_kg] IS NULL AND [weighing_2_kg] IS NULL AND [weight_kg] IS NULL OR [requires_weighing]=(1) AND [weighing_1_kg]>(0) AND [weighing_2_kg] IS NULL AND [weight_kg] IS NULL OR [requires_weighing]=(1) AND [weighing_1_kg]>(0) AND [weighing_2_kg]>(0) AND [weight_kg]=([weighing_2_kg]-[weighing_1_kg])))
GO
ALTER TABLE [dbo].[admission_form] CHECK CONSTRAINT [CK_admission_form_weight_kg]
GO
